import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_empty(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 3, 4], 2, 7), ([1, 2], 0, 0), ([1, 2], 5, 3),
     ([1, 2], 2, 3), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # comment, not,a,record",
             " x1 , 3 , 1 \n", "x2, -2 , 0", " x3 , 4 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": -2, "flagged": False},
        {"id": "x3", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", " \t", "ok,1,0", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    old = {"id": "a", "day": 9, "flagged": True}
    middle = {"id": "a", "day": 7, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": None}
    b = {"id": "b", "day": 2, "flagged": True}
    c = {"id": "c", "day": 1, "flagged": False}
    events = [old, b, middle, c, last]
    assert dedupe_transcripts(events) == [c, last, b]
    assert events == [old, b, middle, c, last]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_gaps_and_outside_events():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 3, "flagged": None},
        {"day": 5, "flagged": True},
        {"day": 6, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounded_rate_calendar_window_and_nonempty_groups():
    groups = {
        "a": [{"id": "a", "day": 1, "flagged": True}],
        "b": [{"id": "b", "day": 4, "flagged": True},
              {"id": "c", "day": 6, "flagged": None}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_ranking_ties_empty_groups_and_limit():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [{"flagged": False}],
        "b": [],
        "a": [{"flagged": True}, {"flagged": None}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.5, "b": None, "z": 0.0}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, 2, -1, 3], 2), ([1, 0, 1, 0, 1], 1), ([2, 3, 4], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
